(()=>{const board=document.querySelector('#board'),economy=window.PixelEconomy,scoreEl=document.querySelector('#score'),bestEl=document.querySelector('#best'),status=document.querySelector('#status');let grid,score,previous=null,won=false;bestEl.textContent=localStorage.game2048Best||0;function spawn(forcedValue){const empty=[];grid.forEach((r,y)=>r.forEach((v,x)=>{if(!v)empty.push([y,x])}));if(empty.length){const [y,x]=empty[Math.random()*empty.length|0];grid[y][x]=forcedValue|| (Math.random()<.9?2:4)}}function draw(){board.innerHTML='';grid.flat().forEach(v=>{const cell=document.createElement('div');cell.className='tile-cell';cell.setAttribute('role','gridcell');cell.dataset.v=v||'';cell.textContent=v||'';board.append(cell)});scoreEl.textContent=score;bestEl.textContent=localStorage.game2048Best||0}function reset(){grid=Array.from({length:4},()=>Array(4).fill(0));score=0;won=false;previous=null;spawn();spawn();if(economy.owns('2048_seed'))spawn(4);status.textContent='Use arrow keys or swipe to slide the tiles.';draw()}function move(d){const old=grid.map(r=>r.slice()),oldScore=score;let moved=false;for(let i=0;i<4;i++){let coords=[];for(let j=0;j<4;j++){let y=d==='up'?j:d==='down'?3-j:i,x=d==='left'?j:d==='right'?3-j:i;coords.push([y,x])}let vals=coords.map(([y,x])=>grid[y][x]).filter(Boolean),out=[];for(let j=0;j<vals.length;j++){if(vals[j]===vals[j+1]){out.push(vals[j]*2);score+=vals[j]*2;j++}else out.push(vals[j])}while(out.length<4)out.push(0);coords.forEach(([y,x],j)=>{if(grid[y][x]!==out[j])moved=true;grid[y][x]=out[j]})}if(!moved){score=oldScore;return}previous={grid:old,score:oldScore};spawn();economy.progress('2048',score-oldScore,40);if(score>+(localStorage.game2048Best||0))localStorage.game2048Best=score;draw();if(!won&&grid.flat().includes(2048)){won=true;status.textContent='You made 2048! Keep going or start a new board.'}else if(!canMove())status.textContent='Board full! Undo a move or start a new game.';else status.textContent='Nice move — keep combining!'}function canMove(){if(grid.flat().includes(0))return true;for(let y=0;y<4;y++)for(let x=0;x<4;x++)if((x<3&&grid[y][x]===grid[y][x+1])||(y<3&&grid[y][x]===grid[y+1][x]))return true;return false}const keys={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};document.addEventListener('keydown',e=>{if(keys[e.key]){e.preventDefault();move(keys[e.key])}});document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>move(b.dataset.dir));document.querySelector('#restart').onclick=reset;document.querySelector('#undo').onclick=()=>{if(previous){grid=previous.grid;score=previous.score;previous=null;status.textContent='Undid your last move.';draw()}};let sx=0,sy=0;board.addEventListener('touchstart',e=>{sx=e.changedTouches[0].clientX;sy=e.changedTouches[0].clientY},{passive:true});board.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.max(Math.abs(dx),Math.abs(dy))>20)move(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'))},{passive:true});reset()})();
